using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SourceFallbackActualChecks {
 static VideoContent Content(string text){return new VideoContent{Version=1,VideoId="V0000000001",Language="ko",Source="YouTube 공개 자막",AcquiredAt=DateTime.UtcNow.ToString("o"),Cues=new List<CaptionCue>{new CaptionCue{Text=text}}};}
 public static int Main(string[] args){try{string runtime=Path.Combine(args[0],"extension/.runtime/replier-llm");var video=new Video{Id="V0000000001",Title="상자를 열어 봤습니다"};var content=Content("열심히 상자를 열었는데 안에 아무것도 없네요.");var json=new JavaScriptSerializer();
 using(var model=new LocalModel(runtime,"gemma4:e2b-it-qat")){
 var planner=new ReactionPlanner(model);var plan=planner.Prepare(video,content,CancellationToken.None).GetAwaiter().GetResult();string quote=(string)CaptionService.Get(json.DeserializeObject(plan.Values.First()),"selected");if(quote!=content.Cues[0].Text)throw new Exception("ordinary source lost");Console.WriteLine("PASS real selector accepts ordinary gameplay without technical terms: "+quote);
 bool rejected=false;try{planner.Prepare(video,Content("제가 추천하는 필살기 무료 게임은 순수 재미 고트입니다."),CancellationToken.None).GetAwaiter().GetResult();}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("pure introduction was selected");Console.WriteLine("PASS real selector still rejects promotional introduction");model.Unload().GetAwaiter().GetResult();}
 using(var service=new DualCommentService(runtime)){var result=service.Generate(video,content,CancellationToken.None).GetAwaiter().GetResult();var best=result.Batches.Where(b=>b.Result!=null).SelectMany(b=>b.Result.Comments).Where(c=>c.FitEligible==true).OrderByDescending(c=>c.FitScore).FirstOrDefault();var report=new{video=video,source=content.Cues[0].Text,best=best,result=result};File.WriteAllText(Path.Combine(args[0],"extension/data/replier-grounded-checks/source-fallback-actual.json"),json.Serialize(report));if(best==null || !result.Complete || !string.IsNullOrEmpty(result.ScoreError))throw new Exception("no approved ordinary-gameplay reaction: "+result.ScoreError);Console.WriteLine("PASS actual dual-model pipeline: "+best.Text);}
 return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}

